      "vi": "Nay đến chuyện bất nghĩa lớn nhất là đem quân đánh nước khác, người đời lại chẳng biết lên án, còn hùa theo ca ngợi và gọi đó là nghĩa.",
      "en": "Yet when it comes to the greatest wrong of attacking another state, people fail to condemn it, instead praising the act and calling it righteousness.",
      "scholarlyCommentaryVi": "Bằng phương pháp quy nạp so sánh giữa hành vi trộm cắp nhỏ và chiến tranh xâm lược, Mặc Tử phơi bày tiêu chuẩn kép đạo đức của giới quân chủ Chiến Quốc. Lập luận logic chặt chẽ này phản ánh lập trường phản chiến thực tế nhằm bảo vệ sinh kế của tầng lớp thợ thủ công và nông dân.",
      "scholarlyCommentaryEn": "Through an inductive analogy comparing petty theft to military aggression, Mozi exposes the moral double standard of Warring States rulers. This logical critique expresses a practical anti-war stance aimed at protecting the livelihoods of artisans and farmers."
