      "vi": "Quan lại không mãi mãi sang quý, dân thường không suốt đời hèn kém; ai có tài năng thì cất nhắc, kẻ bất tài thì giáng xuống.",
      "en": "Officials are not perpetually noble, nor are commoners forever lowly; promote those with ability, and demote those without it.",
      "scholarlyCommentaryVi": "Học thuyết Thượng Hiền của Mặc Tử tấn công trực tiếp vào chế độ thế tập cha truyền con nối đã mục ruỗng từ cuối thời Xuân Thu. Nguyên tắc trọng dụng nhân tài bất kể xuất thân này mở đường cho sự dịch chuyển xã hội của tầng lớp sĩ và bình dân tri thức.",
      "scholarlyCommentaryEn": "Mozi's doctrine of elevating the worthy directly challenges the hereditary aristocracy that had decayed by the late Spring and Autumn period. This meritocratic principle regardless of birth opened pathways for upward mobility among scholars and skilled commoners."
