      "en": "Bodhi originally has no tree, nor does the bright mirror have a stand. From the beginning not a single thing exists, so where could dust alight.",
      "scholarlyCommentaryVi": "Bài kệ của Lục Tổ Huệ Năng đáp lại bài kệ tiệm tu của Thần Tú, đánh dấu bước ngoặt lý luận của Nam tông Thiền dựa trên tinh thần Bát Nhã tánh không. Thay vì miệt mài lau chùi phiền não như vật thể bên ngoài, Huệ Năng khẳng định giác ngộ là sự trực nhận bản tâm vốn thanh tịnh.",
      "scholarlyCommentaryEn": "Huineng's verse responds to Shenxiu's gradualist poem, marking the doctrinal turn of Southern Chan rooted in Prajnaparamita emptiness. Rather than treating defilements as external dust to be wiped away, Huineng affirms awakening as direct insight into the originally pure mind."
