      "scholarlyCommentaryEn": "Chan Master Linji Yixuan emphasizes the absolute autonomy of the awakened subject, rejecting reliance on external authority or textual formalism. The terse vernacular syntax reflects the direct, incisive teaching style that defined the Linji lineage in the late Tang dynasty."
