      "scholarlyCommentaryEn": "This Classical Chinese verse concluding Emperor Tran Nhan Tong's Cu Tran Lac Dao condenses the engaged spirit of the Truc Lam Yen Tu Chan school. Practice does not require withdrawal from daily life or civic duty, but rests in living naturally while keeping the mind unperturbed by circumstances."
