      "bookingAlertVi": "Vé tàu 12306 tại Ga Bắc Tây An gắn trực tiếp với số hộ chiếu; Bảo tàng Lịch sử Thiểm Tây đóng cửa thứ Hai và phát hành vé trước 5 ngày theo khung giờ cố định trên Mini Program WeChat, trong khi Bảo tàng Lăng Tần Thủy Hoàng mở đặt trước 7 ngày bằng hộ chiếu."
