      "passageZh": "全长七点八公里的北京中轴线，北起钟鼓楼，南至永定门，串联起故宫、景山、天安门广场及天坛、先农坛等十五处核心遗产构成要素。这一宏大的空间营建格局始于元大都时期，历经明清两代持续扩建完善，集中体现了《考工记》中“面朝后市、左祖右社”的古典都城规划理念。中轴线以严谨的左右对称结构统筹国家礼仪空间与市民市井生活：皇城宫殿居于中心高位，太庙与社稷坛分列东西两侧，南北两端则分别布局报时建筑与城门防御体系，形成起伏有致、层次分明的建筑视觉序列。二零二四年该遗产正式列入《世界遗产名录》后，当代城市更新面临的新课题在于如何在高密度现代都市中严格守护历史天际线与视觉通廊。通过腾退占压遗迹的现代违建、疏解核心区过度集中的商业功能并修复传统胡同街巷肌理，北京正尝试让古老的轴线秩序继续服务于当代市民的日常公共生活。",
