      "passageZh": "纵贯中国南北的京杭大运河沟通了海河、黄河、淮河、长江与钱塘江五大水系，是古代世界里程最长、工程最为复杂的人工航道。由于沿线地势起伏悬殊，尤其是山东南旺段海拔最高，长期成为制约满载税粮的漕船翻越“水脊”的最大瓶颈。北宋时期，淮南转运副使乔维岳在淮阴首创双门“复闸”，通过轮流启闭上下闸门调节闸室内水位，使船只得以逐级平缓爬升，大幅降低了传统单闸骤然放水造成的船体损毁与水量流失。至明代永乐年间，水利专家宋礼与民间工匠白英主持修建戴村坝，巧妙拦截汶水并引至南旺分水口，实现了“七分朝天子，三分下江南”的精准配水方案，同时配建沿线水柜以备旱季补水。进入二十一世纪后，这条古老航道被纳入南水北调东线工程，借助现代梯级泵站与跨流域生态调水机制，持续改善华北平原地下水超采与河湖湿地萎缩的严峻局面。",
