      "titleVi": "Hệ âm Thiết Vận và giá trị học thuật của âm Hán – Việt trong phục dựng Hán ngữ Trung Cổ",
      "titleEn": "The Qieyun phonological system and the scholarly value of Sino-Vietnamese in Middle Chinese reconstruction",
      "passageZh": "公元六零一年，隋代学者陆法言编纂完成韵书《切韵》，以反切注音的方式系统记录了南北朝至隋唐之际的汉语读书音格局。由于汉字属于语素文字而非表音字母，现代语言学家欲还原一千四百年前的中古汉语实际读音，不能仅凭现存文献字面推测，必须综合比对汉语各方言及周边域外译音材料。在这一比较历史语言学框架中，唐宋时期大规模传入越南并固化下来的“汉越音”具有不可替代的参照意义。与现代北京普通话不同，汉越音完整保留了中古汉语的塞音韵尾与鼻音韵尾分化，例如入声字末尾的清塞音以及双唇鼻音尾在越南语中至今清晰可辨。高本汉、马伯乐与阮才谨等中外学者通过系统对应《切韵》反切上下字、汉越音与日语汉音及朝鲜汉字音，成功勾勒出中古汉语声母清浊分化与声调演变的严密规律，为东亚语言接触史研究奠定了坚实的方法论基础。",
