      "passageZh": "在汉字传播至东亚各地的漫长进程中，周边民族在沿用文言书面语的同时，也积极利用汉字构件创造记录本民族口语的本土文字，其中越南喃字是最具代表性的复杂方块文字体系之一。与日本假名通过草书简化演变为纯表音音节文字不同，喃字始终保持与汉字一致的方块视觉结构，主要借助假借、会意与形声三种造字原则表达越南语固有词汇。其中占比最高的形声字通常由一个表义汉字与一个表音汉字左右或上下拼合而成，如以“百”表义、“林”表音构拟越南语“百”的古音，无意间为后世保留了早于现代国语字的古代复辅音线索。自陈代至阮代，从阮廌的《国音诗集》到阮攸的《金云翘传》，喃字文学构建起独立于汉文官方典籍之外的本土抒情传统。尽管二十世纪后拉丁化的国语字逐步成为通用书写工具，现存数千种汉喃古籍仍是研究越南历史、民俗与东亚语言史的珍贵一手文献。",
