        "Bước 2: Yêu cầu đối tác đóng 公章 hoặc 合同专用章 có mã số định danh rõ nét lên cả trang ký và đóng dấu giáp lai (骑缝章) xuyên suốt toàn bộ các trang hợp đồng.",
