        "vi": "Theo Quy định Cơ chế điều chỉnh biên giới carbon của EU (CBAM, Quy định EU 2023/956), trong vòng 15 ngày sau khi giao mỗi lô phôi thép tiền chất, bên bán phải cung cấp dữ liệu phát thải thực tế gắn liền tại nhà máy sản xuất (gồm phát thải trực tiếp và thuyết minh quy trình luyện thép) đã qua thẩm định bởi tổ chức được công nhận.",
