      "scenarioEn": "A lighting distributor in Hanoi orders 12,000 units of 150W LED power supplies from a factory in Baoan District, Shenzhen for FCL ocean shipment to Hai Phong Port. The contract stipulates 30% deposit and 70% balance payment prior to shipment only after a pre-shipment inspection (PSI) passes ISO 2859-1 General Inspection Level II with AQL Critical 0, Major 2.5, and Minor 4.0.",
