      "actionChecklistVi": [
        "Bước 1: Kiểm tra giấy phép nhập khẩu phân bón và chứng nhận hợp quy tại Việt Nam trước khi tàu rời ga Hà Khẩu Bắc.",
        "Bước 2: Yêu cầu giám định viên chụp ảnh niêm phong mẫu lưu hóa lý và kiểm tra độ ẩm bao bì chống thấm 2 lớp PP/PE tại kho Ngọc Khê.",
        "Bước 3: Đối chiếu khối lượng tịnh, tên thương mại và mã HS 3105.20.00 giữa Form E điện tử, vận đơn đường sắt và tờ khai hải quan Lào Cai."
      ]
