        "vi": "Nếu người chuyên chở ký hợp đồng vận tải đa phương thức này dưới danh nghĩa chi nhánh, phải đính kèm giấy ủy quyền bằng văn bản và thư bảo lãnh trách nhiệm liên đới có đóng Công chương (公章) của tổng công ty, xác nhận rõ trách nhiệm bồi thường tổn thất và chậm trễ hàng hóa trên tuyến đường sắt xuyên biên giới.",
